vec3 rgb2hsv(vec3 c) {
  vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
  float d = q.x - min(q.w, q.y);
  float e = 1.0e-10;
  return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}
vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
vec3 adjustHueSaturation(vec3 color, float hue, float saturation) {
  vec3 hsv = rgb2hsv(color);
  hsv.x = fract(hsv.x + hue / 360.0);
  hsv.y = clamp(hsv.y * saturation, 0.0, 1.0);
  return hsv2rgb(hsv);
}
vec3 adjustContrast(vec3 color, float contrast) {
  return clamp((color - 0.5) * contrast + 0.5, 0.0, 1.0);
}
vec3 adjustBrightness(vec3 color, float brightness) {
  return color * brightness;
}
vec4 getRegionBounds(int region) {
  float sizePx = max(blockSizePx.x, 106.0);
  float isNarrow = step(0.5, blockSizePx.y);
  float outerBorderSize = 2.0 / sizePx;
  float bevelRatio = mix(17.0 / 106.0, 17.0 / sizePx, isNarrow);
  float centerStart = bevelRatio;
  float centerEnd = 1.0 - bevelRatio;
  float innerBorderStart = outerBorderSize;
  float innerBorderEnd = 1.0 - outerBorderSize;
  if (region == 0) {
    return vec4(0.0, 0.0, 1.0, 1.0);
  } else if (region == 1) {
    return vec4(centerStart, centerStart, centerEnd, centerEnd);
  } else if (region == 2) {
    return vec4(innerBorderStart, centerEnd, innerBorderEnd, innerBorderEnd);
  } else if (region == 3) {
    return vec4(innerBorderStart, innerBorderStart, innerBorderEnd, centerStart);
  } else if (region == 4) {
    return vec4(innerBorderStart, innerBorderStart, centerStart, innerBorderEnd);
  } else {
    return vec4(centerEnd, innerBorderStart, innerBorderEnd, innerBorderEnd);
  }
}
vec2 getRegionRelativeUV(vec2 uv, int region) {
  vec4 bounds = getRegionBounds(region);
  vec2 transformedUV = (uv * uvTransform.xy) + uvTransform.zw;
  transformedUV = clamp(transformedUV, 0.0, 1.0);
  vec2 regionSize = bounds.zw - bounds.xy;
  vec2 regionUV = (transformedUV - bounds.xy) / regionSize;
  return clamp(regionUV, 0.0, 1.0);
}
vec3 applyBlendMode(vec3 base, vec3 blend, float mode) {
  if (mode < 0.5) {
    return mix(base, blend, 1.0);
  } else if (mode < 1.5) {
    return base * blend;
  } else if (mode < 2.5) {
    vec3 overlay1 = 2.0 * base * blend;
    vec3 overlay2 = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
    vec3 result;
    result.r = base.r < 0.5 ? overlay1.r : overlay2.r;
    result.g = base.g < 0.5 ? overlay1.g : overlay2.g;
    result.b = base.b < 0.5 ? overlay1.b : overlay2.b;
    return result;
  } else if (mode < 3.5) {
    return 1.0 - (1.0 - base) * (1.0 - blend);
  } else if (mode < 4.5) {
    vec3 soft1 = base - (1.0 - 2.0 * blend) * base * (1.0 - base);
    vec3 soft2 = base + (2.0 * blend - 1.0) * (sqrt(base) - base);
    vec3 result;
    result.r = blend.r < 0.5 ? soft1.r : soft2.r;
    result.g = blend.g < 0.5 ? soft1.g : soft2.g;
    result.b = blend.b < 0.5 ? soft1.b : soft2.b;
    return result;
  } else if (mode < 5.5) {
    vec3 hard1 = 2.0 * base * blend;
    vec3 hard2 = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
    vec3 result;
    result.r = blend.r < 0.5 ? hard1.r : hard2.r;
    result.g = blend.g < 0.5 ? hard1.g : hard2.g;
    result.b = blend.b < 0.5 ? hard1.b : hard2.b;
    return result;
  } else if (mode < 6.5) {
    return min(base, blend);
  } else if (mode < 7.5) {
    return max(base, blend);
  } else {
    return clamp(base + blend - 1.0, 0.0, 1.0);
  }
}
vec3 applySingleLayerAdjustments(vec3 color, vec2 uv, float brightness, float contrast, float saturation, float hue,
