  if (blendModeEnable > 0.5) {
    color = applyBlendMode(color, tintColor.rgb, blendMode);
    color = adjustBrightness(color, brightness);
    color = adjustContrast(color, contrast);
    color = adjustHueSaturation(color, hue, saturation);
  } else {
    vec3 targetColor = tintColor.rgb;
    targetColor = adjustBrightness(targetColor, brightness);
    targetColor = adjustContrast(targetColor, contrast);
    targetColor = adjustHueSaturation(targetColor, hue, saturation);
    color = targetColor;
  }
  if (gradientEnable > 0.5 && gradientStrength > 0.0) {
    float gradientFactor = 0.0;
    if (gradientType < 0.5) {
      float angleRad = radians(gradientDirection);
      vec2 gradientDir = vec2(cos(angleRad), sin(angleRad));
      vec2 centeredUV = uv - vec2(0.5);
      float projection = dot(centeredUV, gradientDir);
      gradientFactor = (projection + 0.707) / 1.414;
    } else {
      gradientFactor = length(uv - vec2(0.5)) * 2.0;
    }
    gradientFactor = clamp(gradientFactor, 0.0, 1.0);
    float outerMixAmount = 0.0;
    if (gradientStrength <= 0.5) {
      outerMixAmount = gradientFactor * (gradientStrength * 2.0);
    } else {
      float enhanceFactor = (gradientStrength - 0.5) * 2.0;
      outerMixAmount = gradientFactor + (gradientFactor * enhanceFactor * 0.5);
    }
    outerMixAmount = clamp(outerMixAmount, 0.0, 1.0);
    color = mix(color, gradientColor.rgb, outerMixAmount);
  }
  return color;
}
vec4 applyColorAdjustments(vec4 originalColor, vec2 uv, int region) {
  vec3 color = originalColor.rgb;
