      color, uv,
      rp.brightness, rp.contrast, rp.saturation, rp.hue,
      rp.colorParam, rp.gradientParam,
      rp.gradientStrength, rp.blendMode,
      rp.gradientDirection, rp.gradientType,
      rp.gradientEnable, rp.blendModeEnable
