  float isNarrow = step(0.5, blockSizePx.y);
  float outerBorderSize = 2.0 / sizePx;
  float bevelRatio = mix(17.0 / 106.0, 17.0 / sizePx, isNarrow);
  float centerStart = bevelRatio;
  float centerEnd = 1.0 - bevelRatio;
  float innerBorderStart = outerBorderSize;
  float innerBorderEnd = 1.0 - outerBorderSize;
  if (uv.x < outerBorderSize || uv.x > innerBorderEnd ||
      uv.y < outerBorderSize || uv.y > innerBorderEnd) {
    return 0;
  }
  if (uv.x >= centerStart && uv.x <= centerEnd &&
      uv.y >= centerStart && uv.y <= centerEnd) {
    return 1;
  }
  float bottomExtent = 1.0 - 2.0 * outerBorderSize;
  if (uv.y > centerEnd && uv.y <= innerBorderEnd) {
    float trapezoidHeight = innerBorderEnd - centerEnd;
    float progress = (uv.y - centerEnd) / trapezoidHeight;
    float topWidth = centerEnd - centerStart;
    float widthExpansion = (bottomExtent - topWidth) * progress * 0.5;
    float leftBound = centerStart - widthExpansion;
    float rightBound = centerEnd + widthExpansion;
    if (uv.x >= leftBound && uv.x <= rightBound) {
      return 3;
    }
  }
  if (uv.y < centerStart && uv.y >= innerBorderStart) {
    float trapezoidHeight = centerStart - innerBorderStart;
    float progress = (centerStart - uv.y) / trapezoidHeight;
    float topWidth = centerEnd - centerStart;
    float widthExpansion = (bottomExtent - topWidth) * progress * 0.5;
    float leftBound = centerStart - widthExpansion;
    float rightBound = centerEnd + widthExpansion;
    if (uv.x >= leftBound && uv.x <= rightBound) {
      return 2;
    }
  }
  if (uv.x < centerStart && uv.x >= innerBorderStart) {
    float trapezoidWidth = centerStart - innerBorderStart;
    float progress = (centerStart - uv.x) / trapezoidWidth;
    float topHeight = centerEnd - centerStart;
    float heightExpansion = (bottomExtent - topHeight) * progress * 0.5;
    float bottomBound = centerStart - heightExpansion;
    float topBound = centerEnd + heightExpansion;
    if (uv.y >= bottomBound && uv.y <= topBound) {
      return 4;
    }
  }
  if (uv.x > centerEnd && uv.x <= innerBorderEnd) {
    float trapezoidWidth = innerBorderEnd - centerEnd;
    float progress = (uv.x - centerEnd) / trapezoidWidth;
    float topHeight = centerEnd - centerStart;
    float heightExpansion = (bottomExtent - topHeight) * progress * 0.5;
    float bottomBound = centerStart - heightExpansion;
    float topBound = centerEnd + heightExpansion;
    if (uv.y >= bottomBound && uv.y <= topBound) {
      return 5;
    }
  }
  return 0;
}
void main () {
      vec4 o = vec4(1, 1, 1, 1);
  vec2 scaledUV = v_uv0;
  #if USE_TEXTURE
  o = texture2D(texture, scaledUV);
  #endif
  o *= v_color;
  ALPHA_TEST(o);
  int region = getRegion(scaledUV);
  o = applyColorAdjustments(o, scaledUV, region);
  if(rightParams3.w > 0.5) {
    vec2 gemsBgUV = (scaledUV - vec2(0.5)) / 0.65 + vec2(0.5);
    vec4 gemsBg = texture2D(gemsBgTexture, gemsBgUV);
    if(gemsBg.a > 0.0&& gemsBgUV.x >= 0.0 && gemsBgUV.x <= 1.0 && gemsBgUV.y >= 0.0 && gemsBgUV.y <= 1.0) {
        o.rgb = mix(o.rgb, gemsBg.rgb, gemsBg.a);
    }
    vec2 gemsUV = (scaledUV - vec2(0.5)) / 0.65 + vec2(0.5);
    vec4 gems = texture2D(gemsTexture, gemsUV);
    if(gems.a > 0.0&& gemsUV.x >= 0.0 && gemsUV.x <= 1.0 && gemsUV.y >= 0.0 && gemsUV.y <= 1.0) {
        o.rgb = mix(o.rgb, gems.rgb, gems.a);
    }
  }
  gl_FragColor = o;
}

